    );
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let nested = snap
        .entities
        .iter()
        .find(|(_, r)| r.name == "g" && r.parent.is_some())
        .map(|(id, _)| *id)
        .expect("nested g");
    let file_g = snap
        .entities
        .iter()
        .find(|(_, r)| r.name == "g" && r.parent.is_none())
        .map(|(id, _)| *id)
        .expect("file g");
    let next = rename(&store, &snap, nested, "helper").unwrap();
